import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Animal } from '../../animales/entities/animal.entity';
import { Cuidador } from '../../cuidadores/entities/cuidador.entity';

@Injectable()
export class AsignarCuidadorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Animal) private readonly animales: Repository<Animal>,
    @InjectRepository(Cuidador) private readonly cuidadores: Repository<Cuidador>
  ) {}

  buscarAnimalRepository(animalId: number) {
    return this.animales.findOneBy({ id: animalId });
  }

  buscarCuidadorRepository(cuidadorId: number) {
    return this.cuidadores.findOneBy({ id: cuidadorId });
  }

  async asignarCuidadorRepository(animalId: number, cuidadorId: number, rol: string) {
    const asignacion = { animalId, cuidadorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarCuidadorRepository } from './repository';

@Injectable()
export class AsignarCuidadorService {
  constructor(private readonly repository: AsignarCuidadorRepository) {}

  async asignarCuidadorService(animalId: number, cuidadorId: number, rol: string) {
    const animal = await this.repository.buscarAnimalRepository(animalId);
    const cuidador = await this.repository.buscarCuidadorRepository(cuidadorId);
    if (!animal || !cuidador) {
      throw new NotFoundException('No existe el animal o el cuidador');
    }

    try {
      return await this.repository.asignarCuidadorRepository(animalId, cuidadorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El cuidador ya está asignado a ese animal');
      }
      throw error;
    }
  }
}

